const languageNames = { en:'English', 'zh-Hant-HK':'繁體中文', 'zh-CN':'简体中文' };
function translationsFor(pathname){
  const group=translationGroups.find(paths=>paths.includes(pathname));
  if(!group)return [];
  return [
    {lang:'en',path:group[0]},
    {lang:'zh-Hant-HK',path:group[1]},
    {lang:'zh-CN',path:group[2]},
  ];
}
function languageLinks(page){return translationsFor(page.path).filter(item=>item.path!==page.path).map(item=>`<a class="button secondary" lang="${item.lang}" hreflang="${item.lang}" href="${item.path}">${languageNames[item.lang]}</a>`).join('');}

