function relatedBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const prefix=cn?'/zh-cn':(zh?'/zh-hk':'/en');const external=p.externalReference?`<a rel="external" href="${p.externalReference[1]}">${esc(p.externalReference[0])}</a>`:'';return `<section class="related"><div class="wrap"><h2>${cn?'相关交付证据':(zh?'相關交付證據':'Related delivery evidence')}</h2><a href="${prefix}/case-studies/retail-ai-decision-platform/">${cn?'零售 AI 决策平台案例':(zh?'零售 AI 決策平台案例':'Retail AI decision platform case study')}</a><a href="${prefix}/case-studies/accounting-ai-production-platform/">${cn?'AI 原生会计生产平台案例':(zh?'AI 原生會計生產平台案例':'AI-native accounting production platform case study')}</a><a href="${prefix}/methodology/case-study-evidence-register/">${cn?'案例证据登记册':(zh?'案例證據登記冊':'Case-study evidence register')}</a>${zh?'':`<a href="/en/insights/what-is-forward-deployed-engineering/">What is Forward Deployed Engineering?</a>`}${external}</div></section>`;}
function serviceBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const home=cn?'/zh-cn/':(zh?'/zh-hk/':'/en/');const localizedDownloadLabel=p.downloadLabel?.[cn?'cn':(zh?'zh':'en')]||(cn?'下载采购评分卡':(zh?'下載採購評分卡':'Download procurement scorecard'));const downloadUseHeading=p.downloadName==='Enterprise AI pilot charter and acceptance record'?(cn?'如何使用试点章程':(zh?'如何使用試點章程':'How to use the pilot charter')):(cn?'如何使用评分卡':(zh?'如何使用評分卡':'How to use the scorecard'));const primaryAction=p.dataUrl?`<a class="button" href="${p.dataUrl}" type="application/json">${cn?'下载证据数据集':(zh?'下載證據數據集':'Download evidence dataset')}</a>`:(p.downloadUrl?`<a class="button" href="${p.downloadUrl}" type="application/json">${localizedDownloadLabel}</a>`:`<a class="button" href="mailto:info@onyxdevslab.com?subject=${encodeURIComponent(p.h1)}">${cn?'预约项目评估':(zh?'預約項目評估':'Book a project assessment')}</a>`);const sourceHeading=p.sourceHeading||(cn?'监管依据与范围':(zh?'監管依據與範圍':'Regulatory sources and scope'));const sourceIntro=p.sourceIntro||(cn?'以下链接是本文采用的一手监管资料。本页提供实施解读，不构成法律意见。':(zh?'以下連結是本文採用的一手監管資料。本頁提供實施解讀，不構成法律意見。':'These are the primary regulator materials used by this implementation guide. This page is not legal advice.'));const sources=p.sourceReferences?`<section><div class="wrap"><h2>${esc(sourceHeading)}</h2><p class="intro">${esc(sourceIntro)}</p><div class="related">${p.sourceReferences.map(([name,url])=>`<a rel="external" href="${url}">${esc(name)}</a>`).join('')}</div></div></section>`:'';return `<main id="content"><div class="wrap breadcrumbs"><a href="${home}">${cn?'首页':(zh?'首頁':'Home')}</a> / ${esc(p.eyebrow)}</div><section class="hero"><div class="wrap"><div class="eyebrow">${esc(p.eyebrow)}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.lede)}</p><div class="actions">${primaryAction}${languageLinks(p)}</div></div></section><div class="wrap proof">${p.proof.map(x=>`<div><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('')}</div>${p.sections.map(s=>`<section><div class="wrap"><h2>${esc(s[0])}</h2><p class="intro">${esc(s[1])}</p><div class="grid">${s[2].map(c=>`<article class="card"><h3>${esc(c[0])}</h3><p>${esc(c[1])}</p></article>`).join('')}</div></div></section>`).join('')}<section><div class="wrap"><h2>${p.dataUrl?(cn?'使用方法':(zh?'使用方法':'How to use the register')):(p.downloadUrl?downloadUseHeading:(cn?'交付方法':(zh?'交付方法':'Delivery method')))}</h2><div class="steps">${p.steps.map(s=>`<div class="step"><div><h3>${esc(s[0])}</h3><p class="intro">${esc(s[1])}</p></div></div>`).join('')}</div></div></section>${sources}${relatedBody(p)}<section class="faq"><div class="wrap"><h2>${cn?'常见问题':(zh?'常見問題':'Frequently asked questions')}</h2>${p.faqs.map(f=>`<details><summary>${esc(f[0])}</summary><p>${esc(f[1])}</p></details>`).join('')}<div class="cta"><h2>${cn?'从一个具体业务问题开始。':(zh?'從一個具體業務問題開始。':'Start with one concrete operating problem.')}</h2><p class="intro">${cn?'我们会先确认流程、证据、数据边界和结果标准，再建议下一步。':(zh?'我們會先確認流程、證據、數據邊界及成果標準，再建議下一步。':'We will first clarify the workflow, evidence, data boundary, and outcome standard before recommending the next step.')}</p><a class="button" href="mailto:info@onyxdevslab.com">${cn?'联系 Onyx':(zh?'聯絡 Onyx':'Contact Onyx')}</a></div></div></section></main>`;}
function evidenceRegisterBody(p){const zh=p.lang.startsWith('zh');const cn=p.lang==='zh-CN';const languageKey=cn?'cn':(zh?'zh':'en');const entries=cases.filter(page=>page.lang===p.lang).map(page=>{const metricKey=page.metricKey||(page.path.includes('retail-')?'retail':'accounting');const metrics=caseValidation[metricKey][languageKey];return `<article class="card"><h3><a href="${page.path}">${esc(page.h1)}</a></h3><ul>${metrics.map(([value,name,definition])=>`<li><strong>${esc(value)} · ${esc(name)}</strong> — ${esc(definition)}</li>`).join('')}</ul><p><strong>${cn?'证据边界':(zh?'證據邊界':'Evidence boundary')}:</strong> ${esc(page.evidence)}</p></article>`;}).join('');const register=`<section><div class="wrap"><h2>${cn?'六个案例的指标登记':(zh?'六個案例的指標登記':'Metric register for six cases')}</h2><p class="intro">${cn?'每项指标都保留数值、名称、测量定义、来源页和证据边界。':(zh?'每項指標均保留數值、名稱、量度定義、來源頁及證據邊界。':'Every metric retains its value, name, measurement definition, source page, and evidence boundary.')}</p><div class="grid">${entries}</div></div></section>`;return serviceBody(p).replace('</main>',`${register}</main>`);}
function caseBody(p){
  const zh=p.lang.startsWith('zh');
  const cn=p.lang==='zh-CN';
  const validationKey=p.metricKey||(p.path.includes('retail-')?'retail':'accounting');
  const metrics=caseValidation[validationKey][cn?'cn':(zh?'zh':'en')];
  const home=cn?'/zh-cn/':(zh?'/zh-hk/':'/en/');
  return `<main id="content"><div class="wrap breadcrumbs"><a href="${home}">${cn?'首页':(zh?'首頁':'Home')}</a> / ${cn?'案例':(zh?'案例':'Case studies')}</div><section class="hero"><div class="wrap"><div class="eyebrow">${cn?'案例 · 交付证据':(zh?'案例 · 交付證據':'Case study · Delivery evidence')}</div><h1>${esc(p.h1)}</h1><p class="lede">${esc(p.lede)}</p><div class="actions">${languageLinks(p)}</div></div></section><section><div class="wrap"><h2>${cn?'业务问题':(zh?'營運問題':'The operating challenge')}</h2><p class="intro">${esc(p.challenge)}</p></div></section><section><div class="wrap"><h2>${cn?'系统干预':(zh?'系統干預':'Designed intervention')}</h2><div class="grid">${p.work.map((x,i)=>`<article class="card"><div class="eyebrow">0${i+1}</div><p>${esc(x)}</p></article>`).join('')}</div></div></section><section><div class="wrap"><h2>${cn?'验证快照':(zh?'驗證快照':'Validation snapshot')}</h2><p class="intro">${cn?'以下数据同时展示已完成范围与试点验证结果；每项指标保留测量口径，避免把产品范围误解为业务结果。':(zh?'以下數據同時呈現已完成範圍與試點驗證結果；每項指標保留口徑，避免把產品範圍誤解為業務成果。':'These figures separate delivered scope from pilot validation. Each metric retains its measurement definition so product coverage is not mistaken for business impact.')}</p><div class="metric-grid">${metrics.map(([value,label,detail])=>`<article class="metric"><strong>${esc(value)}</strong><h3>${esc(label)}</h3><p>${esc(detail)}</p></article>`).join('')}</div></div></section><section><div class="wrap"><h2>${cn?'证据边界':(zh?'證據邊界':'Evidence boundary')}</h2><p class="intro">${esc(p.evidence)}</p><div class="cta"><h2>${cn?'讨论一个相近的业务问题。':(zh?'討論一個相近的營運問題。':'Discuss a comparable operating problem.')}</h2><a class="button" href="mailto:info@onyxdevslab.com?subject=Case%20study%20enquiry">${cn?'预约项目评估':(zh?'預約項目評估':'Book a project assessment')}</a></div></div></section></main>`;
}
